import{_ as s,c as i,o as e,b0 as t}from"./chunks/framework.Dmsv_Tiv.js";const n="/media-docs/assets/image-20240622144924936.CGEx_Qna.png",l="/media-docs/assets/image-20251218111542793.BEgLC1m0.jpg",p="/media-docs/assets/image-20251218111743806.BWznKZu0.jpg",r="/media-docs/assets/image-20251218111958508.93y573Cv.png",h="/media-docs/assets/image-20251218112056509.B_Rr13aF.png",d="data:image/png;base64,",o="/media-docs/assets/image-20251218112218867.Drp52xhP.png",V="data:image/png;base64,",c="/media-docs/assets/image-20221101140216424.CNEC9JJl.jpg",Y="/media-docs/assets/2022-10-26-20-32-31.CuQ1EwvE.png",k="/media-docs/assets/image-20240622171227455.DR3iJs-8.png",U="/media-docs/assets/image-20240622171938988.B6xaWJp2.png",g="/media-docs/assets/image-20251218115106940.CgJd7yYK.png",m="/media-docs/assets/image-20251218115129842.BoxYnPml.png",u="/media-docs/assets/image-20251218115159020.DVkLGgDv.png",F="/media-docs/assets/YUV-format.iYQd94lN.png",A="data:image/png;base64,",b="/media-docs/assets/image-20240622193503749.C69ErOcH.png",y="/media-docs/assets/image-20240622194845908.CEnBOY4i.png",W=JSON.parse('{"title":"LV020-YUV的格式","description":null,"frontmatter":{"title":"LV020-YUV的格式","date":"2025-09-19T13:54:32.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/image/color-model/126b08d768c80d2ccc082ecc","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-09-19T13:54:32.210Z","fulluuid":"ccc082ecce0f423ab0a8921f377eff61","useduuid":"ccc082ecc"}},"headers":[],"relativePath":"sdoc/image/color-model/126b08d768c80d2ccc082ecc.md","filePath":"sdoc/01-图像/20-常用色彩模型/LV020-YUV的格式.md","lastUpdated":1767537778000}'),C={name:"sdoc/image/color-model/126b08d768c80d2ccc082ecc.md"};function B(E,a,v,x,f,q){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="lv020-yuv的格式" tabindex="-1">LV020-YUV的格式 <a class="header-anchor" href="#lv020-yuv的格式" aria-label="Permalink to &quot;LV020-YUV的格式&quot;">​</a></h1><h2 id="一、yuv采样模式" tabindex="-1">一、YUV采样模式 <a class="header-anchor" href="#一、yuv采样模式" aria-label="Permalink to &quot;一、YUV采样模式&quot;">​</a></h2><h3 id="_1-采样模式有哪些" tabindex="-1">1. 采样模式有哪些？ <a class="header-anchor" href="#_1-采样模式有哪些" aria-label="Permalink to &quot;1. 采样模式有哪些？&quot;">​</a></h3><h4 id="_1-1-四种采样模式" tabindex="-1">1.1 四种采样模式 <a class="header-anchor" href="#_1-1-四种采样模式" aria-label="Permalink to &quot;1.1 四种采样模式&quot;">​</a></h4><p>YUV 有 4 种采样模式：</p><ul><li>YUV4:4:4 ，表示完全采样，一个像素 占 3 个字节。</li><li>YUV4:2:2，表示2:1的水平采样，垂直完全采样，平均一个像素占 2 个字节。</li><li>YUV4:2:0，表示2:1的水平采样，垂直2:1采样，平均一个像素占 1.5 个字节。</li><li>YUV4:1:1，表示4:1的水平采样，垂直完全采样，但是这种我只是在维基百科的词条中看到有，实际并没有接触过。</li></ul><p>主流的采样模式就是前面三种，YUV444、YUV422和YUV420。这些是什么意思？后面会详细学习，这样的采样模式主要是因为由于人眼对 Y 的敏感度远超于对 U 和 V 的敏感，所以有时候可以多个 Y 分量共用一组 UV，这样既可以极大得节省空间，又可以不太损失质量。这三种格式就是按照人眼的特性制定的。</p><p>YUV格式之所以能够采用不同的采样模式，核心原因在于<strong>人眼的生理特性</strong>：</p><p>（1）人眼对亮度（Y）的敏感度远高于对色度（U/V）的敏感度</p><ul><li>亮度分量（Y）包含图像的细节信息，人眼对此非常敏感</li><li>色度分量（U/V）包含颜色信息，人眼对此相对不敏感</li></ul><p>（2）视觉感知的不对称性</p><ul><li>人眼能够分辨出微小的亮度变化，但对颜色的细微变化不敏感</li><li>即使大幅减少色度信息，人眼也很难察觉到明显的质量损失</li></ul><h4 id="_1-2-图片示例" tabindex="-1">1.2 图片示例 <a class="header-anchor" href="#_1-2-图片示例" aria-label="Permalink to &quot;1.2 图片示例&quot;">​</a></h4><p>我们可以准备一张图片，使用FFmpeg转换一下，分别得到YUV444、YUV422和YUV420格式的图片，方便后面分析。可以直接在这里下载：<a href="https://wwz.lanzouj.com/iet4d22f7bha" target="_blank" rel="noreferrer">yuv-picture.zip</a>：</p><img src="'+n+`" alt="image-20240622144924936" style="zoom:50%;"><p>我们也可以自己找一张jpg图片，转换一下，相关命令如下所示：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ffmpeg.exe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> juren.jpg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1920</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -pix_fmt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yuvj444p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> juren_yuv_444.yuv</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ffmpeg.exe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> juren.jpg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1920</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -pix_fmt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yuvj422p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> juren_yuv_422.yuv</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ffmpeg.exe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> juren.jpg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1920</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -pix_fmt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yuvj420p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> juren_yuv_420.yuv</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>从上图可以看到，yuv420 比 yuv444 的 数据量少了一半，我们用 <a href="http://datahammer.de/" target="_blank" rel="noreferrer">7yuv</a> 看一下图片质量的差异：</p><table><tbody><tr style="border:none;"><td align="center" style="border:none;"> juren_yuv_444.yuv（注意格式那里选YUV444 planar）<br><img src="`+l+'" alt="image-20251218111542793" style="width:100%;height:auto;"></td><td align="center" style="border:none;"> juren_yuv_420.yuv（注意格式那里选YUV420 planar I420）<br><img src="'+p+'" alt="image-20251218111743806" style="width:100%;height:auto;"></td></tr></tbody></table><p>观察上面两张图，至少我是没有觉察到有什么变化，所以<strong>重点：YUV420 比 YUV444 少了一半数据，视觉体验几乎没有变化。</strong></p><h3 id="_2-不同采样模式" tabindex="-1">2. 不同采样模式 <a class="header-anchor" href="#_2-不同采样模式" aria-label="Permalink to &quot;2. 不同采样模式&quot;">​</a></h3><h4 id="_2-1-yuv444" tabindex="-1">2.1 YUV444 <a class="header-anchor" href="#_2-1-yuv444" aria-label="Permalink to &quot;2.1 YUV444&quot;">​</a></h4><p>YUV 4:4:4 采样，意味着 Y、U、V 三个分量的采样比例相同，因此在生成的图像里，每个像素的三个分量信息完整，都是 8 bit，也就是一个字节。</p><p>这种格式占用空间最大，每个像素点有一个Y分量 + 一个U分量 + 一个V分量所以和 RGB 一样每个像素点占用3个字节！但是根据UV存储顺序不一样，又可能会有两种不同的格式，这种的就属于存储格式了，后面再说。</p><p><img src="'+r+`" alt="image-20251218111958508"></p><p>如上图所示，YUV444就是每个像素点都包含了三个完整的YUV分量，每一个Y分量用一组UV分量，所以</p><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单个像素点占用的空间为: pixel = 1Byte(Y) + 1Byte(U) + 1Byte(V) = 3Byte</span></span>
<span class="line"><span>一帧图像占用的空间为  : frameSize = (frameWidth * frameHeight * 3)Byte</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><blockquote><p>例如</p><p>假如图像像素为：[Y0 U0 V0]、[Y1 U1 V1]、[Y2 U2 V2]、[Y3 U3 V3] 那么采样的码流为：Y0 U0 V0 Y1 U1 V1 Y2 U2 V2 Y3 U3 V3 最后映射出的像素点依旧为 [Y0 U0 V0]、[Y1 U1 V1]、[Y2 U2 V2]、[Y3 U3 V3]</p></blockquote><h4 id="_2-2-yuv422" tabindex="-1">2.2 YUV422 <a class="header-anchor" href="#_2-2-yuv422" aria-label="Permalink to &quot;2.2 YUV422&quot;">​</a></h4><p>YUV 4:2:2 采样，意味着 UV 分量是 Y 分量采样的一半，Y 分量和 UV 分量按照 2 : 1 的比例采样。如果水平方向有 10 个像素点，那么采样了 10 个 Y 分量，而只采样了 5 个 UV 分量。</p><p><img src="`+h+'" alt="image-20251218112056509"></p><p>YUV422就是UV分量是Y分量的一半，按照上图的样子，应该是相邻两个Y共用一个UV：</p><p><img src="'+d+`" alt="image-20251218112125627"></p><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单个像素点占用的空间为: pixel = 1Byte(Y) + 1Byte(U)/2 + 1Byte(V)/2 = 2Byte</span></span>
<span class="line"><span>一帧图像占用的空间为  : frameSize = (frameWidth * frameHeight * 2)Byte</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><blockquote><p>举个例子 ：</p><p>假如图像像素为：[Y0 U0 V0]、[Y1 U1 V1]、[Y2 U2 V2]、[Y3 U3 V3]</p><p>那么采样的码流为：Y0 U0 Y1 V1 Y2 U2 Y3 V3</p><p>其中，每采样过一个像素点，都会采样其 Y 分量，而 U、V 分量就会间隔一个采集一个。</p><p>最后映射出的像素点为 [Y0 U0 V1]、[Y1 U0 V1]、[Y2 U2 V3]、[Y3 U2 V3]</p></blockquote><p>采样的码流映射为像素点，还是要满足每个像素点有 Y、U、V 三个分量。但是可以看到，第一和第二像素点公用了 U0、V1 分量，第三和第四个像素点公用了 U2、V3 分量，这样就节省了图像空间。一张 1280 x 720 大小的图片，在 YUV 4:2:2 采样时的大小为：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">1280x720x8</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1280x720x8x0.5</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1280x720x8x0.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1024</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1024</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1.76M</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>可以看到 YUV 4:2:2 采样的图像比 RGB 模型图像节省了三分之一的存储空间，在传输时占用的带宽也会随之减少。</p><h4 id="_2-3-yuv420" tabindex="-1">2.3 YUV420 <a class="header-anchor" href="#_2-3-yuv420" aria-label="Permalink to &quot;2.3 YUV420&quot;">​</a></h4><p>这个格式也是应用最广泛的，视频会议，数字电视，DVD，都用的 YUV420 格式。YUV 4:2:0 采样，并不是指只采样 U 分量而不采样 V 分量。而是指，在每一行扫描时，只扫描一种色度分量（U 或者 V），和 Y 分量按照 2 : 1 的方式采样。比如，第一行扫描时，YU 按照 2 : 1 的方式采样，那么第二行扫描时，YV 分量按照 2:1 的方式采样。对于每个色度分量来说，它的水平方向和竖直方向的采样和 Y 分量相比都是 2:1 。</p><p><img src="`+o+'" alt="image-20251218112218867"></p><p>如上图，假设第一行扫描了 U 分量，第二行扫描了 V 分量，那么需要扫描两行才能够组成完整的 UV 分量。所以四个像素点才能包含一组完整的YUV信息：</p><p><img src="'+V+`" alt="image-20251218112248355"></p><p>第一行的第1，第2 像素，第二行的 第1，第2 像素共用一组 UV，以此类推。为什么不是 第一行的 第 1~ 4 个像素共享 一组 UV？这是因为如果这样搞，空间距离太远，容易造成体验不太好。换行共享 UV 的空间距离短，画面过渡会自然一些。所以四个Y分量共用一组UV分分量：</p><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单个像素点占用的空间为: pixel = 1Byte(Y) + 1Byte(U)/4 + 1Byte(V)/4 = 1.5Byte</span></span>
<span class="line"><span>一帧图像占用的空间为  : frameSize = (frameWidth * frameHeight * 1.5)Byte</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><blockquote><p>举个例子 ：</p><p>假设图像像素为：</p><p>[Y0 U0 V0]、[Y1 U1 V1]、 [Y2 U2 V2]、 [Y3 U3 V3] [Y5 U5 V5]、[Y6 U6 V6]、 [Y7 U7 V7] 、[Y8 U8 V8]</p><p>那么采样的码流为：Y0 U0 Y1 Y2 U2 Y3 Y5 V5 Y6 Y7 V7 Y8</p><p>其中，每采样过一个像素点，都会采样其 Y 分量，而 U、V 分量就会间隔一行按照 2 : 1 进行采样。</p><p>最后映射出的像素点为：</p><p>[Y0 U0 V5]、[Y1 U0 V5]、[Y2 U2 V7]、[Y3 U2 V7] [Y5 U0 V5]、[Y6 U0 V5]、[Y7 U2 V7]、[Y8 U2 V7]</p></blockquote><p>这些 UV 值都是新值，是以前的 4 个像素的 U 值加起来 除以4 的平均值。其实有好几种求 UV 值算法：</p><p>（1）平均值，4 个像素的 U 值加起来 除以 4。</p><p>（2）加权，例如，第一第二个像素的 U 权重大点，第三第四个像素的 U 权重小一点。</p><p>（3）直接丢弃 第二，第三，第四个像素的 U 值，取 第一个 像素的 U 值。V 值同理。</p><p>一张 1280 * 720 大小的图片，在 YUV 4:2:0 采样时的大小为：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">1280</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 720</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1280</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 720</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.25</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2）/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1024</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1024</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MB</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>可以看到 YUV 4:2:0 采样的图像比 RGB 模型图像节省了一半的存储空间，因此它也是比较主流的采样方式。</p><h3 id="_3-总结" tabindex="-1">3. 总结 <a class="header-anchor" href="#_3-总结" aria-label="Permalink to &quot;3. 总结&quot;">​</a></h3><table><tbody><tr><td><img src="`+c+'" alt="image-20221101140216424" style="zoom:100%;"></td><td><img src="'+Y+'" style="zoom:100%;"></td></tr></tbody></table><p>如上图所示：</p><table tabindex="0"><thead><tr><th>YUV格式</th><th>每个像素所占字节数</th><th>说明</th></tr></thead><tbody><tr><td>YUV444</td><td>pixel_size=1Byte(Y)+1Byte(U)+1Byte(V)=3Byte</td><td>每个Y对应一组UV</td></tr><tr><td>YUV422</td><td>pixel_size=[2Byte(Y)+1Byte(Y)+1Byte(V)]/2=2Byte</td><td>每2个Y对应一组UV</td></tr><tr><td>YUV420</td><td>pixel_size=[4Byte(Y)+1Byte(Y)+1Byte(V)]/4=1.5Byte</td><td>每4个Y对应一组UV</td></tr></tbody></table><h2 id="二、存储格式" tabindex="-1">二、存储格式 <a class="header-anchor" href="#二、存储格式" aria-label="Permalink to &quot;二、存储格式&quot;">​</a></h2><h3 id="_1-有哪些格式" tabindex="-1">1. 有哪些格式？ <a class="header-anchor" href="#_1-有哪些格式" aria-label="Permalink to &quot;1. 有哪些格式？&quot;">​</a></h3><p>上面了解了采样模式了，那采样结束肯定需要存储的啊，怎么存？YUV存储方式主要分为三种：压缩格式（Packed formats） 、平面格式（Planar formats）和半平面（semi-Planar）。</p><table><tbody><tr><td align="center" width="200px">存储格式</td><td align="center">说明</td></tr><tr><td align="left">P：Planner</td><td align="left">按平面分开存放，先把Y存完，再存U，再存V，就是先连续存储所有像素点的Y，紧接着存储所有像素点的U，随后是所有像素点的V，即YYY UUU VVV 这样</td></tr><tr><td align="left">SP：semi-Planar</td><td align="left">按半平面存放，只有Y是一个平面，UV数据共用一个平面，UV分量交叉存储。</td></tr><tr><td align="left">Packed</td><td align="left">打包格式，就是把YUV三种分量按顺序存储，即YUV YUV YUV ... 这样</td></tr></tbody></table><p>所以不同的采样方式加上不同的存储方式就会有多种不同的YUV编码方式。</p><h3 id="_2-常用的格式" tabindex="-1">2. 常用的格式 <a class="header-anchor" href="#_2-常用的格式" aria-label="Permalink to &quot;2. 常用的格式&quot;">​</a></h3><h4 id="_2-1-yuv420" tabindex="-1">2.1 YUV420 <a class="header-anchor" href="#_2-1-yuv420" aria-label="Permalink to &quot;2.1 YUV420&quot;">​</a></h4><p>YUV420是使用很多的，它结合不同的存储方式，常用的会有YUV420P和YUV420SP。</p><h5 id="_2-1-1-yuv420p" tabindex="-1">2.1.1 YUV420P <a class="header-anchor" href="#_2-1-1-yuv420p" aria-label="Permalink to &quot;2.1.1 YUV420P&quot;">​</a></h5><p>YUV420P属于YUV420采样，planar存储，它又会分为YU12（也叫 l420）、YV12两种，YU12 和 YV12 格式都属于 YUV 420P 类型，即先存储 Y 分量，再存储 U、V 分量，区别在于：YU12 是先 Y 再 U 后 V，而 YV12 是先 Y 再 V 后 U 。</p><img src="'+k+'" alt="image-20240622171227455" style="zoom:50%;"><p>I420（属于 YUV 420 Plannar） I420 是 YUV 420 Planar 的一种，YUV 分量分别存放，先是 w * h 长度的 Y，后面跟 w * h * 0.25 长度的 U， 最后是 w * h * 0.25 长度的 V，总长度为 w * h * 1.5。</p><p>YV12（属于 YUV 420 Plannar） YV12 是 YUV 420 Planar 的一种，YUV 分量分别存放，先是 w * h 长度的 Y，后面跟 w * h * 0.25 长度的 V， 最后是 w * h * 0.25 长度的 U，总长度为 w * h * 1.5。与 I420 不同的是，YV12 是先 V 后 U。</p><h5 id="_2-1-2-yuv420sp" tabindex="-1">2.1.2 YUV420SP <a class="header-anchor" href="#_2-1-2-yuv420sp" aria-label="Permalink to &quot;2.1.2 YUV420SP&quot;">​</a></h5><p>YUV420SP属于YUV420采样，semi-Planar存储，分为NV12、NV21，YUV420先存储了 Y 分量，但接下来并不是再存储所有的 U 或者 V 分量，而是把 UV 分量交替连续存储。NV12 是 IOS 中有的模式，它的存储顺序是先存 Y 分量，再 UV 进行交替存储。NV21 是 安卓中有的模式，它的存储顺序是先存 Y 分量，在 VU 交替存储。</p><img src="'+U+'" alt="image-20240622171938988" style="zoom:50%;"><p>NV12（属于 YUV 420 Semi-Planar） NV12 是 YUV 420 Semi-Planar 的一种，Y 分量单独存放，UV 分量交错存放，UV 在排列的时候，从 U 开始。总长度为 w * h * 1.5。</p><p>NV21（属于 YUV 420 Semi-Planar） NV21 是 YUV 420 Semi-Planar 的一种，Y 分量单独存放，UV 分量交错存放，与 NV12 不同的是，UV 在排列的时候，从 V 开始。总长度为 w * h * 1.5。</p><h4 id="_2-2-yuv422-1" tabindex="-1">2.2 YUV422 <a class="header-anchor" href="#_2-2-yuv422-1" aria-label="Permalink to &quot;2.2 YUV422&quot;">​</a></h4><h5 id="_2-2-1-yuv422p" tabindex="-1">2.2.1 YUV422P <a class="header-anchor" href="#_2-2-1-yuv422p" aria-label="Permalink to &quot;2.2.1 YUV422P&quot;">​</a></h5><p>YUV422P属于YUV422采样，它的存储格式是planar，分YU16和YV16两种：</p><p><img src="'+g+'" alt="image-20251218115106940"></p><p>I422（属于 YUV 422 Plannar，也叫YU16） I422 是 YUV 422 Planar 的一种，YUV 分量分别存放，先是 w * h 长度的 Y，后面跟 w * h * 0.5 长度的 U， 最后是 w * h * 0.5 长度的 V，总长度为 w * h * 2。</p><p>YV16（属于 YUV 422 Plannar） YV16 是 YUV 422 Planar 的一种，YUV 分量分别存放，先是 w * h 长度的 Y，后面跟 w * h * 0.5 长度的 V， 最后是 w * h * 0.5 长度的 U，总长度为 w * h * 2。与 I422 不同的是，YV16 是先 V 后 U。</p><h5 id="_2-2-2-yuv422sp" tabindex="-1">2.2.2 YUV422SP <a class="header-anchor" href="#_2-2-2-yuv422sp" aria-label="Permalink to &quot;2.2.2 YUV422SP&quot;">​</a></h5><p>YUV422SP 属于YUV422采样，分为NV16、NV61两种：</p><p><img src="'+m+'" alt="image-20251218115129842"></p><p>NV16（属于 YUV 422 Semi-Planar） NV16 是 YUV 422 Semi-Planar 的一种，Y 分量单独存放，UV 分量交错存放，UV 在排列的时候，从 U 开始。总长度为 w * h * 2。</p><p>NV61（属于 YUV 422 Semi-Planar） NV61 是 YUV 422 Semi-Planar 的一种，Y 分量单独存放，UV 分量交错存放，UV 在排列的时候，从 V 开始。总长度为 w * h * 2。</p><h5 id="_2-2-3-packed格式" tabindex="-1">2.2.3 Packed格式 <a class="header-anchor" href="#_2-2-3-packed格式" aria-label="Permalink to &quot;2.2.3 Packed格式&quot;">​</a></h5><p><img src="'+u+'" alt="image-20251218115159020"></p><p>YUVY（属于 YUV 422 Interleaved） YUVY 属于 YUV 422 Interleaved 的一种。事实上，Interleaved 是属于 Packed 的，但是在 422 中，用 Interleaved 更加形象一些。在 Packed 内部，YUV 的排列顺序是 Y U V Y，两个 Y 共用一组 UV。</p><p>UYVY（属于 YUV 422 Interleaved） UYVY 属于 YUV 422 Interleaved 的一种。在 Packed 内部，YUV 的排列顺序是 UYVY，两个 Y 共用一组 UV。</p><h2 id="三、总结" tabindex="-1">三、总结 <a class="header-anchor" href="#三、总结" aria-label="Permalink to &quot;三、总结&quot;">​</a></h2><p>其中打包格式（如YUYV）多见于老旧采集设备，现代系统已逐步淘汰。其实用的多的还是YUV420，其中NV12，NV21较为常见。</p><img src="'+F+'" alt="YUV格式" style="zoom:100%;"><h2 id="四、yuv图片数据分析" tabindex="-1">四、YUV图片数据分析 <a class="header-anchor" href="#四、yuv图片数据分析" aria-label="Permalink to &quot;四、YUV图片数据分析&quot;">​</a></h2><p>YUV 这种格式的文件，不像 BMP 文件，BMP 虽然里面也是 RGB 的裸数据，但是 BMP 里面有一些头数据，宽高什么的。</p><p>但是 YUV文件格式，没有头信息，没有宽高信息，所以用 7yuv 打开 YUV 文件的时候，需要指定宽高，要指定采样格式是 4:4:4。如果我们有一个 YUV图片，但是忘记了 它的宽高跟采样格式，那就无法正常显示这个 YUV图片。</p><p>所以，YUV图片文件除了 原始的像素数据，什么都没有的。由于 4:4:4 跟 RGB24 一样，每个像素占 3 字节，图片宽高是 1920x1080 ，所以这个 YUV图片的大小如下：</p><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SIZE=1920x1080x3=6075KB</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>可以看到，它的大小确实也是6075KB左右：</p><img src="'+A+'" alt="image-20240622193154796" style="zoom:67%;"><p>我们用notpad++打开juren_yuv_444.yuv文件，这里还需要用插件来查看十六进制数据才行。</p><img src="'+b+'" alt="image-20240622193503749" style="zoom:50%;"><p>会发现开头数据大量是0，看一下图片会发现开头大部分都是全黑的像素点，那我们来修改一下这个YUV文件，在最开始修改的话不是很好改，我们大概确定一个位置，我们想在第20行开始将像素点全部改为FF，这样起始地址大概就是1920x3x20=115200=1C200，我们大概就从这个地址附近选一个开始，直接插入FF数据，我们放大一点看：</p><img src="'+y+'" alt="image-20240622194845908" style="zoom:50%;"><p>发现确实出现了白线。</p><blockquote><p>参考资料</p><p><a href="https://www.cnblogs.com/yongdaimi/p/10647005.html" target="_blank" rel="noreferrer">数字音视频技术: 谈谈 YUV的采样格式和存储格式 - 夜行过客 - 博客园</a></p><p><a href="https://blog.csdn.net/weixin_40877924/article/details/106266195" target="_blank" rel="noreferrer">学习YUV编码格式及存储方式，看这篇就够了_yuyv格式-CSDN博客</a></p><p><a href="https://zhuanlan.zhihu.com/p/113122344" target="_blank" rel="noreferrer">一文读懂 YUV 的采样与格式 - 知乎</a></p><p><a href="https://zhuanlan.zhihu.com/p/384455058" target="_blank" rel="noreferrer">YUV 格式详解，只看这一篇就够了（转） - 知乎</a></p></blockquote>',106)])])}const P=s(C,[["render",B]]);export{W as __pageData,P as default};
